#ifndef INCLUDED_SAL_OSL_W32_PATH_HELPER_HXX
#define INCLUDED_SAL_OSL_W32_PATH_HELPER_HXX

#include <sal/config.h>

#include <osl/diagnose.h>
#include <sal/types.h>

namespace osl
{
template< class T >
class LongPathBuffer
{
    T* m_pBuffer;
    sal_uInt32 m_nCharNum;

    LongPathBuffer() = delete;
    LongPathBuffer(const LongPathBuffer&) = delete;
    LongPathBuffer& operator=(const LongPathBuffer&) = delete;

public:
    explicit LongPathBuffer( sal_uInt32 nCharNum )
    : m_pBuffer( static_cast<T*>( malloc( nCharNum * sizeof( T ) ) ) )
    , m_nCharNum( nCharNum )
    {
        OSL_ENSURE( m_pBuffer, "Can not allocate the buffer!" );
    }

    ~LongPathBuffer()
    {
        if ( m_pBuffer )
            free( m_pBuffer );
        m_pBuffer = nullptr;
    }

    sal_uInt32 getBufSizeInSymbols()
    {
        return m_nCharNum;
    }

    operator T* ()
    {
        return m_pBuffer;
    }

};

} // end namespace osl

#endif

